import MD from './_md-map.js';

// page path -> Markdown copy (generated by tools/build-agent-files.py), plus the reverse for canonicals
const PAGE_FOR_MD = {};
for (const [page, md] of Object.entries(MD)) if (!(md in PAGE_FOR_MD) && !page.endsWith('.html')) PAGE_FOR_MD[md] = page;

export async function onRequest({ request, next, env }) {
  const url = new URL(request.url);

  // Canonical host: send www.thirstybeaches.com to the apex with a 301, keeping path + query.
  if (url.hostname === 'www.thirstybeaches.com') {
    url.hostname = 'thirstybeaches.com';
    return Response.redirect(url.toString(), 301);
  }
  if (request.method !== 'GET' && request.method !== 'HEAD') return next();

  const md = MD[url.pathname];
  const wantsMarkdown = (request.headers.get('accept') || '').includes('text/markdown');

  // AI agents that ask for Markdown get the page's Markdown copy (same content, ~80% fewer tokens).
  if (md && wantsMarkdown) {
    const res = await env.ASSETS.fetch(new URL(md, url.origin));
    if (res.ok) return markdownResponse(res, url.origin + canonicalPath(url.pathname));
  }

  // Direct .md requests: right content type, and point search engines at the HTML page as canonical.
  if (PAGE_FOR_MD[url.pathname]) {
    const res = await next();
    if (res.ok) return markdownResponse(res, url.origin + PAGE_FOR_MD[url.pathname]);
    return res;
  }

  const res = await next();
  if (md && res.ok && (res.headers.get('content-type') || '').includes('text/html')) {
    const out = new Response(res.body, res);
    out.headers.append('Link', `<${md}>; rel="alternate"; type="text/markdown"`);
    out.headers.append('Vary', 'Accept');
    return out;
  }
  return res;
}

function canonicalPath(path) {
  if (path === '/index.html') return '/';
  return path.endsWith('.html') ? path.slice(0, -5) : path;
}

function markdownResponse(res, canonical) {
  const out = new Response(res.body, res);
  out.headers.set('Content-Type', 'text/markdown; charset=utf-8');
  out.headers.set('Link', `<${canonical}>; rel="canonical"`);
  out.headers.append('Vary', 'Accept');
  out.headers.set('Cache-Control', 'public, max-age=0, must-revalidate');
  return out;
}
